Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
dmaengine: stm32-dmamux: Fix PM disable depth imbalance in
 stm32_dmamux_probe

The pm_runtime_enable will increase power disable depth.
If the probe fails, we should use pm_runtime_disable() to balance
pm_runtime_enable().

Fixes: 4f3ceca254e0 ("dmaengine: stm32-dmamux: Add PM Runtime support")
Signed-off-by: Miaoqian Lin <linmq006@gmail.com>
Reviewed-by: Amelie Delaunay <amelie.delaunay@foss.st.com>
Link: https://lore.kernel.org/r/20220108085336.11992-1-linmq006@gmail.com
Signed-off-by: Vinod Koul <vkoul@kernel.org>

Here is the root cause:
The bug arises from an imbalance in the power management runtime calls, specifically when `pm_runtime_enable()` is called but not properly balanced with `pm_runtime_disable()` if the probe fails during the execution of the `of_dma_router_register` function. This can lead to an incorrect power management state, potentially causing issues in device power management.

Here is the patch:

 static int stm32_dmamux_probe(struct platform_device *pdev)
 {
 	struct device_node *node = pdev->dev.of_node;
 	const struct of_device_id *match;
 	struct device_node *dma_node;
 	struct stm32_dmamux_data *stm32_dmamux;
 	struct resource *res;
 	void __iomem *iomem;
 	struct reset_control *rst;
 	int i, count, ret;
 	u32 dma_req;

 	if (!node)
 		return -ENODEV;

 	count = device_property_count_u32(&pdev->dev, "dma-masters");
 	if (count < 0) {
 		dev_err(&pdev->dev, "Can't get DMA master(s) node\n");
 		return -ENODEV;
 	}

 	stm32_dmamux = devm_kzalloc(&pdev->dev, sizeof(*stm32_dmamux) +
 				    sizeof(u32) * (count + 1), GFP_KERNEL);
 	if (!stm32_dmamux)
 		return -ENOMEM;

 	dma_req = 0;
 	for (i = 1; i <= count; i++) {
 		dma_node = of_parse_phandle(node, "dma-masters", i - 1);

 		match = of_match_node(stm32_stm32dma_master_match, dma_node);
 		if (!match) {
 			dev_err(&pdev->dev, "DMA master is not supported\n");
 			of_node_put(dma_node);
 			return -EINVAL;
 		}

 		if (of_property_read_u32(dma_node, "dma-requests",
 					 &stm32_dmamux->dma_reqs[i])) {
 			dev_info(&pdev->dev,
 				 "Missing MUX output information, using %u.\n",
 				 STM32_DMAMUX_MAX_DMA_REQUESTS);
 			stm32_dmamux->dma_reqs[i] =
 				STM32_DMAMUX_MAX_DMA_REQUESTS;
 		}
 		dma_req += stm32_dmamux->dma_reqs[i];
 		of_node_put(dma_node);
 	}

 	if (dma_req > STM32_DMAMUX_MAX_DMA_REQUESTS) {
 		dev_err(&pdev->dev, "Too many DMA Master Requests to manage\n");
 		return -ENODEV;
 	}

 	stm32_dmamux->dma_requests = dma_req;
 	stm32_dmamux->dma_reqs[0] = count;
 	stm32_dmamux->dma_inuse = devm_kcalloc(&pdev->dev,
 					       BITS_TO_LONGS(dma_req),
 					       sizeof(unsigned long),
 					       GFP_KERNEL);
 	if (!stm32_dmamux->dma_inuse)
 		return -ENOMEM;

 	if (device_property_read_u32(&pdev->dev, "dma-requests",
 				     &stm32_dmamux->dmamux_requests)) {
 		stm32_dmamux->dmamux_requests = STM32_DMAMUX_MAX_REQUESTS;
 		dev_warn(&pdev->dev, "DMAMUX defaulting on %u requests\n",
 			 stm32_dmamux->dmamux_requests);
 	}
 	pm_runtime_get_noresume(&pdev->dev);

 	res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
 	iomem = devm_ioremap_resource(&pdev->dev, res);
 	if (IS_ERR(iomem))
 		return PTR_ERR(iomem);

 	spin_lock_init(&stm32_dmamux->lock);

 	stm32_dmamux->clk = devm_clk_get(&pdev->dev, NULL);
 	if (IS_ERR(stm32_dmamux->clk))
 		return dev_err_probe(&pdev->dev, PTR_ERR(stm32_dmamux->clk),
 				     "Missing clock controller\n");

 	ret = clk_prepare_enable(stm32_dmamux->clk);
 	if (ret < 0) {
 		dev_err(&pdev->dev, "clk_prep_enable error: %d\n", ret);
 		return ret;
 	}

 	rst = devm_reset_control_get(&pdev->dev, NULL);
 	if (IS_ERR(rst)) {
 		ret = PTR_ERR(rst);
 		if (ret == -EPROBE_DEFER)
 			goto err_clk;
 	} else {
 		reset_control_assert(rst);
 		udelay(2);
 		reset_control_deassert(rst);
 	}

 	stm32_dmamux->iomem = iomem;
 	stm32_dmamux->dmarouter.dev = &pdev->dev;
 	stm32_dmamux->dmarouter.route_free = stm32_dmamux_free;

 	platform_set_drvdata(pdev, stm32_dmamux);
 	pm_runtime_set_active(&pdev->dev);
 	pm_runtime_enable(&pdev->dev);

 	pm_runtime_get_noresume(&pdev->dev);

 	/* Reset the dmamux */
 	for (i = 0; i < stm32_dmamux->dma_requests; i++)
 		stm32_dmamux_write(stm32_dmamux->iomem, STM32_DMAMUX_CCR(i), 0);

 	pm_runtime_put(&pdev->dev);

 	ret = of_dma_router_register(node, stm32_dmamux_route_allocate,
 				     &stm32_dmamux->dmarouter);
 	if (ret)
-		goto err_clk;
+		goto pm_disable;

 	return 0;

+pm_disable:
+	pm_runtime_disable(&pdev->dev);
 err_clk:
 	clk_disable_unprepare(stm32_dmamux->clk);

 	return ret;
 }



